command:
$ErrorActionPreference="Stop"
$repo="C:\dev\flyExplorer"
$main="ef9dbf16495e4911c59492ea43eec1a4b0e06bef"
$candidate="82b1e8b663dc05207f059b6c7aa2fbebc213e7d5"
$branch="work/current-release-packaging-20261005"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("current-release-packaging-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
$cacheJunction=$null
try{
  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree failed"}
  $sharedCache=Join-Path $repo ".cache\nuget"
  if(Test-Path -LiteralPath $sharedCache -PathType Container){
    $cacheParent=Join-Path $temp ".cache"
    New-Item -ItemType Directory -Force -Path $cacheParent | Out-Null
    $cacheJunction=Join-Path $cacheParent "nuget"
    New-Item -ItemType Junction -Path $cacheJunction -Target $sharedCache | Out-Null
  }

  Set-Location -LiteralPath $temp
  $env:PYTHONIOENCODING="utf-8"
  & python -X utf8 tools\winui\check_python_static.py tests\winui\test_installed_lifecycle.py tests\winui\test_installer_contract.py
  if($LASTEXITCODE -ne 0){throw "changed installer harness static check failed"}
  & python -X utf8 tests\winui\test_installer_contract.py
  if($LASTEXITCODE -ne 0){throw "installer contract failed"}
  & git diff --check ($main+".."+$candidate)
  if($LASTEXITCODE -ne 0){throw "candidate diff check failed"}

  & .\clean.bat build
  if($LASTEXITCODE -ne 0){throw "clean build output failed"}
  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "canonical Release build failed"}

  & python -X utf8 packaging\provenance.py --write
  if($LASTEXITCODE -ne 0){throw "payload provenance generation failed"}
  & python -X utf8 packaging\provenance.py --check
  if($LASTEXITCODE -ne 0){throw "payload provenance verification failed"}

  & .\package.bat Release
  if($LASTEXITCODE -ne 0){throw "current Release package build failed"}
  & python -X utf8 tests\winui\test_installed_lifecycle.py
  if($LASTEXITCODE -ne 0){throw "bounded installed lifecycle failed"}

  $evidence=Join-Path $repo "logs\remote-evidence"
  New-Item -ItemType Directory -Force -Path $evidence | Out-Null
  Copy-Item -LiteralPath (Join-Path $temp "packaging\licenses\PAYLOAD_PROVENANCE.md") -Destination (Join-Path $evidence "PAYLOAD_PROVENANCE.md") -Force
  Copy-Item -LiteralPath (Join-Path $temp "packaging\licenses\PAYLOAD_PROVENANCE.json") -Destination (Join-Path $evidence "PAYLOAD_PROVENANCE.json") -Force
  $setup=Join-Path $temp "out\package\flyExplorer-Setup-x64.exe"
  $setupHash=(Get-FileHash -Algorithm SHA256 -LiteralPath $setup).Hash.ToLowerInvariant()
  $prov=Get-Content -Raw -Encoding UTF8 -LiteralPath (Join-Path $temp "packaging\licenses\PAYLOAD_PROVENANCE.json") | ConvertFrom-Json
  [ordered]@{
    candidate_sha=$candidate
    setup_sha256=$setupHash
    setup_bytes=(Get-Item -LiteralPath $setup).Length
    runtime_files=$prov.runtime_file_count
    product_generated_files=$prov.product_generated_file_count
    nuget_matched_files=$prov.nuget_matched_file_count
    runtime_manifest_sha256=$prov.runtime_manifest_sha256
    lifecycle="PASS"
  } | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath (Join-Path $evidence "packaging-result.json") -Encoding UTF8
  Write-Host "CURRENT_RELEASE_PACKAGING_PASS"
}finally{
  Set-Location -LiteralPath $repo
  if($cacheJunction -and (Test-Path -LiteralPath $cacheJunction)){
    cmd /d /c rmdir "$cacheJunction" | Out-Null
  }
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
